/** 備考右クリックメニューを同時に1つだけ表示する */
let activeCloser = null
let globalListenerAttached = false

export function closeActiveNoteContextMenu() {
  if (!activeCloser) return
  const closer = activeCloser
  activeCloser = null
  closer()
}

export function registerNoteContextMenuOpen(onClose) {
  if (activeCloser && activeCloser !== onClose) {
    closeActiveNoteContextMenu()
  }
  activeCloser = onClose
}

export function unregisterNoteContextMenu(onClose) {
  if (activeCloser === onClose) {
    activeCloser = null
  }
}

function onDocumentContextMenu(event) {
  const t = event?.target
  if (!t || typeof t.closest !== 'function') return

  if (t.closest('.snippet-context-menu')) {
    closeActiveNoteContextMenu()
    return
  }

  // 備考 textarea の contextmenu は SlotItem 側で開閉を制御
  if (t.closest('.note-textarea:not([readonly])')) return

  closeActiveNoteContextMenu()
}

export function ensureNoteContextMenuGlobalListener() {
  if (globalListenerAttached) return
  document.addEventListener('contextmenu', onDocumentContextMenu, true)
  globalListenerAttached = true
}
