/**
 * 指示タブ・帳票用: external_code の正規化（写真・テンプレ突合で共用）
 */
export function normalizeExternalCode(raw) {
  let s = String(raw ?? '').trim()
  if (!s) return ''
  if (typeof s.normalize === 'function') {
    s = s.normalize('NFKC')
  }
  return s.replace(/[\uFF01-\uFF5E]/g, (ch) =>
    String.fromCharCode(ch.charCodeAt(0) - 0xfee0)
  )
}

/**
 * アイテム行の原本表示: 5列目（場所）と6列目（内容）を結合。
 * 両方あるときのみ「場所-内容」。片方だけのときは `-` なし。
 */
export function formatItemRowOriginalDisplay(getCellValue, itemRow) {
  const loc = String(getCellValue(itemRow, 4) ?? '').trim()
  const ins = String(getCellValue(itemRow, 5) ?? '').trim()
  if (!loc && !ins) return ''
  if (loc && ins) return `${loc}-${ins}`
  return loc || ins
}

/** アイテム行の6列目（内容）のみ。グリッド書き込み時の原本テキスト取得用 */
export function formatItemRowOriginalInstructionOnly(getCellValue, itemRow) {
  return String(getCellValue(itemRow, 5) ?? '').trim()
}

/**
 * グリッド6列目へ書き込む指示: 原本内容 + 写真集約（片方空ならもう片方のみ）
 */
export function mergeGridInstructionWithPhotoContent(originalInstr, photoContent) {
  const o = String(originalInstr ?? '').trim()
  const p = String(photoContent ?? '').trim()
  if (o && p) return `${o}-${p}`
  return o || p
}

/**
 * エクセル出力用: 原本と写真集約を 原本 { 内容 } 形式で連結
 */
export function mergeGridInstructionWithPhotoContentForExcel(originalInstr, photoContent) {
  const o = String(originalInstr ?? '').trim()
  const p = String(photoContent ?? '').trim()
  if (o && p) return `${o} { ${p} }`
  return o || p
}

/**
 * 同一コード・同一依頼先の写真行を集約した入力欄テキスト（場所は含めない）
 * エクセル出力用: 行間は「･」（半角中黒）、数量は「内容xN」（x の前に半角スペースなし）
 */
export function buildPhotoContentFromMergeGroup(gRows) {
  const contentPieces = []
  const sameContentCount = new Map()
  for (const r of gRows || []) {
    const content = String(r.content ?? '').trim()
    if (!content) continue
    sameContentCount.set(content, (sameContentCount.get(content) || 0) + 1)
  }
  const sameContentQtySum = new Map()
  for (const r of gRows || []) {
    const content = String(r.content ?? '').trim()
    if (!content || (sameContentCount.get(content) || 0) < 2) continue
    const prev = sameContentQtySum.get(content) || 0
    sameContentQtySum.set(content, normalizeQuantityNumber(prev + toNumberOrZero(r.quantity)))
  }
  const emittedSameContent = new Set()
  for (const r of gRows || []) {
    const content = String(r.content ?? '').trim()
    if (content && (sameContentCount.get(content) || 0) >= 2) {
      if (emittedSameContent.has(content)) continue
      emittedSameContent.add(content)
      const summedQty = sameContentQtySum.get(content) || 0
      const summedQtyText = formatPhotoQtyText(summedQty)
      contentPieces.push(`${content}x${summedQtyText || '0'}`)
      continue
    }
    let rowPart = content || ''
    if (r.is_quantity) {
      const qtxt = formatPhotoQtyText(r.quantity)
      if (qtxt) rowPart += `x${qtxt}`
    }
    if (rowPart) contentPieces.push(rowPart)
  }
  return contentPieces.join('･')
}

/**
 * @param {Array<{ id: string, sort_order: number, items?: array }>} slots
 * @param {Record<number, string>} rowToSlotMap row(0-based) -> slotId
 * @param {(row:number,col:number)=>string} getCellValue
 * @param {(row:number)=>number} getRowMod12
 */
export function collectFirstInstructionByCodeFromGrid(slots, rowToSlotMap, getCellValue, getRowMod12) {
  const map = new Map()
  const rows = Object.keys(rowToSlotMap || {})
    .map((k) => Number(k))
    .filter((r) => Number.isFinite(r) && getRowMod12(r) === 1)
    .sort((a, b) => a - b)

  for (const baseRow of rows) {
    const codeRaw = getCellValue(baseRow, 3)
    const key = normalizeExternalCode(codeRaw)
    if (!key || map.has(key)) continue
    const instr = getCellValue(baseRow, 5) || ''
    map.set(key, instr)
  }

  for (const slot of slots || []) {
    if (!slot?.items?.length) continue
    const baseRows = rows.filter((br) => rowToSlotMap[br] === slot.id)
    const baseRow = baseRows[0]
    if (baseRow === undefined) continue
    const sortedItems = [...slot.items].sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
    const mod12Map = { 0: 3, 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 9, 7: 10, 8: 11, 9: 0 }
    for (const item of sortedItems) {
      const targetMod = mod12Map[item.sort_order]
      const itemRow = targetMod === 0 ? baseRow + 11 : baseRow + targetMod - 1
      const c = normalizeExternalCode(getCellValue(itemRow, 3))
      if (!c || map.has(c)) continue
      map.set(c, formatItemRowOriginalDisplay(getCellValue, itemRow))
    }
  }
  return map
}

/**
 * コード（正規化）→ グリッド6列目へ書き込む原本テキスト（親は6列目、アイテム行も6列目のみ）
 * 依頼先不一致で新規スロット挿入するときのフォールバック用。
 */
export function collectFirstGridInstructionOnlyByCodeFromGrid(slots, rowToSlotMap, getCellValue, getRowMod12) {
  const map = new Map()
  const rows = Object.keys(rowToSlotMap || {})
    .map((k) => Number(k))
    .filter((r) => Number.isFinite(r) && getRowMod12(r) === 1)
    .sort((a, b) => a - b)

  for (const baseRow of rows) {
    const codeRaw = getCellValue(baseRow, 3)
    const key = normalizeExternalCode(codeRaw)
    if (!key || map.has(key)) continue
    map.set(key, String(getCellValue(baseRow, 5) ?? '').trim())
  }

  for (const slot of slots || []) {
    if (!slot?.items?.length) continue
    const baseRows = rows.filter((br) => rowToSlotMap[br] === slot.id)
    const baseRow = baseRows[0]
    if (baseRow === undefined) continue
    const sortedItems = [...slot.items].sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
    const mod12Map = { 0: 3, 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 9, 7: 10, 8: 11, 9: 0 }
    for (const item of sortedItems) {
      const targetMod = mod12Map[item.sort_order]
      const itemRow = targetMod === 0 ? baseRow + 11 : baseRow + targetMod - 1
      const c = normalizeExternalCode(getCellValue(itemRow, 3))
      if (!c || map.has(c)) continue
      map.set(c, formatItemRowOriginalInstructionOnly(getCellValue, itemRow))
    }
  }
  return map
}

/**
 * コード（正規化）→ 原本グリッドでそのコードが初めて現れる行の依頼先（MOD12=1 の列5相当 = contractor_id）
 * アイテム行のみに現れるコードは、同一スロット先頭行の依頼先を使う。
 */
export function collectFirstContractorIdByCodeFromGrid(slots, rowToSlotMap, getCellValue, getRowMod12) {
  /** @type {Map<string, string|null>} */
  const map = new Map()
  const rows = Object.keys(rowToSlotMap || {})
    .map((k) => Number(k))
    .filter((r) => Number.isFinite(r) && getRowMod12(r) === 1)
    .sort((a, b) => a - b)

  const normCid = (raw) => {
    const s = String(raw ?? '').trim()
    return s || null
  }

  for (const baseRow of rows) {
    const codeRaw = getCellValue(baseRow, 3)
    const key = normalizeExternalCode(codeRaw)
    if (!key || map.has(key)) continue
    map.set(key, normCid(getCellValue(baseRow, 4)))
  }

  for (const slot of slots || []) {
    if (!slot?.items?.length) continue
    const baseRows = rows.filter((br) => rowToSlotMap[br] === slot.id)
    const baseRow = baseRows[0]
    if (baseRow === undefined) continue
    const headerCid = normCid(getCellValue(baseRow, 4))
    const sortedItems = [...slot.items].sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
    const mod12Map = { 0: 3, 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 9, 7: 10, 8: 11, 9: 0 }
    for (const item of sortedItems) {
      const targetMod = mod12Map[item.sort_order]
      const itemRow = targetMod === 0 ? baseRow + 11 : baseRow + targetMod - 1
      const c = normalizeExternalCode(getCellValue(itemRow, 3))
      if (!c || map.has(c)) continue
      map.set(c, headerCid)
    }
  }
  return map
}

function normalizeContractorIdForMerge(v) {
  if (v == null || v === '') return null
  const s = String(v).trim()
  return s || null
}

function contractorLabelFromList(id, contractorsList) {
  if (!id) return ''
  const hit = (contractorsList || []).find((c) => String(c.id) === String(id))
  return hit?.label ? String(hit.label) : String(id)
}

/** 写真リンク行の依頼先表示（入力欄 contractor_id のみ） */
export function resolveInstructionContractorLabel(linkRow, contractorsList) {
  const cid = normalizeContractorIdForMerge(linkRow?.contractor_id)
  return contractorLabelFromList(cid, contractorsList)
}

/** sort_order → MOD12（EstimateGridEditor と同じ対応） */
const ITEM_SORT_ORDER_TO_MOD12 = { 0: 3, 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 9, 7: 10, 8: 11, 9: 0 }

/**
 * スロット単位で「親行（MOD12=1）→テンプレートアイテム行（sort_order 昇順）」とし、
 * 非空コードセルごとに表示順カウンタを進める。各コードの初出カウンタが指示タブの並びキー。
 * @returns {Map<string, number>} normCode → 表示順（小さいほど上）
 */
export function collectTemplateDisplayRankByNormCodeFromGrid(slots, rowToSlotMap, getCellValue, getRowMod12) {
  /** @type {Map<string, number>} */
  const firstRank = new Map()
  let pos = 0
  const rows = Object.keys(rowToSlotMap || {})
    .map((k) => Number(k))
    .filter((r) => Number.isFinite(r) && getRowMod12(r) === 1)
    .sort((a, b) => a - b)

  const slotById = new Map((slots || []).map((s) => [s.id, s]))

  const note = (raw) => {
    const k = normalizeExternalCode(raw)
    if (!k) return
    if (!firstRank.has(k)) firstRank.set(k, pos)
    pos += 1
  }

  for (const baseRow of rows) {
    const slotId = rowToSlotMap[baseRow]
    const slot = slotById.get(slotId)
    note(getCellValue(baseRow, 3))
    if (slot?.items?.length) {
      const sortedItems = [...slot.items].sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
      for (const item of sortedItems) {
        const targetMod = ITEM_SORT_ORDER_TO_MOD12[item.sort_order]
        const itemRow = targetMod === 0 ? baseRow + 11 : baseRow + targetMod - 1
        note(getCellValue(itemRow, 3))
      }
    }
  }
  return firstRank
}

/**
 * 原本グリッド上でテンプレートに含まれるコードの、表示順（親→子）に沿った初出一覧
 * @returns {string[]}
 */
export function collectOrderedTemplateNormCodesFromGrid(slots, rowToSlotMap, getCellValue, getRowMod12) {
  const rank = collectTemplateDisplayRankByNormCodeFromGrid(slots, rowToSlotMap, getCellValue, getRowMod12)
  return [...rank.entries()].sort((a, b) => a[1] - b[1]).map(([k]) => k)
}

/**
 * 見積タブ用: file_id ごとの links をフラット化
 * @param {Record<string, Array>} linksByFileId
 * @param {Array<{ id: string, original_name?: string }>} filesOrdered
 */
export function flattenPhotoLinksForReadonly(linksByFileId, filesOrdered) {
  const rows = []
  const list =
    filesOrdered && filesOrdered.length > 0
      ? filesOrdered
      : Object.keys(linksByFileId || {})
          .sort()
          .map((id) => ({ id, original_name: id }))
  for (const f of list) {
    const fid = String(f.id)
    const links = linksByFileId[fid] || []
    const name = f.original_name || f.name || fid
    links.forEach((link, idx) => {
      const code = String(link.external_code || '').trim()
      if (!code) return
      rows.push({
        fileId: fid,
        fileName: name,
        rowIndex: idx,
        external_code: link.external_code,
        description: link.description || '',
        content: link.content || '',
        quantity: link.quantity,
        is_quantity: Boolean(link.is_quantity),
        contractor_id: link.contractor_id ?? null
      })
    })
  }
  return rows
}

/**
 * 指示タブ: 写真リンク各行 + テンプレ原本列
 */
/** 写真リンク数量などの集計用（比較ローカル処理からも利用） */
export function toNumberOrZero(v) {
  if (v === null || v === undefined || v === '') return 0
  const n = Number(v)
  return Number.isFinite(n) ? n : 0
}

function normalizeQuantityNumber(v) {
  if (!Number.isFinite(v)) return 0
  const rounded = Math.round(v * 1_000_000) / 1_000_000
  return Object.is(rounded, -0) ? 0 : rounded
}

function formatPhotoQtyText(qty) {
  if (!Number.isFinite(qty) || qty === 0) return ''
  return String(qty).replace(/\.0+$/, '').replace(/(\.\d*?)0+$/, '$1')
}

/**
 * 写真リンク1行分を、旧「指示書反映」と同様の短文にまとめる（Excel 用の追記など）
 */
export function formatPhotoLinkSnippet(link) {
  const qty = toNumberOrZero(link?.quantity)
  const contentSnippet = String(link?.content ?? '').trim()
  const qtyText = formatPhotoQtyText(qty)
  if (link?.is_quantity && qty !== 0) {
    return contentSnippet ? `${contentSnippet}x${qtyText}` : `x${qtyText}`
  }
  return contentSnippet
}

/**
 * 正規化コード → 写真由来の追記テキスト（同一コードは改行区切りで連結）
 */
export function aggregatePhotoSnippetsByNormCode(linksByFileId) {
  /** @type {Map<string, string>} */
  const m = new Map()
  for (const links of Object.values(linksByFileId || {})) {
    for (const link of links || []) {
      const k = normalizeExternalCode(link?.external_code)
      if (!k) continue
      const snip = formatPhotoLinkSnippet(link)
      if (!snip) continue
      const prev = m.get(k)
      m.set(k, prev ? `${prev} / ${snip}` : snip)
    }
  }
  return m
}

function templateHasNormCode(templateInstructionByNormCode, nk) {
  if (!nk) return false
  if (templateInstructionByNormCode instanceof Map) {
    return templateInstructionByNormCode.has(nk)
  }
  return Object.prototype.hasOwnProperty.call(templateInstructionByNormCode || {}, nk)
}

/**
 * 指示タブ用: 写真リンク行 + 原本列を、
 * 1) 原本にコード無し → 正規化コードの昇順（ja）
 * 2) 原本にコードあり → 原本グリッドの「スロット親行→アイテム行（sort_order）」の表示順で初出した位置
 * のあいだでは (1) が先、(2) が後。
 *
 * @param {Map<string, number>|null} templateDisplayRankByNormCode collectTemplateDisplayRankByNormCodeFromGrid
 * @param {{ id: string, label: string }[]|null} contractorsList 依頼先表示名解決用
 */
export function buildInstructionMergeRows(
  linksByFileId,
  filesOrdered,
  templateInstructionByNormCode,
  templateDisplayRankByNormCode = null,
  contractorsList = null
) {
  const flat = flattenPhotoLinksForReadonly(linksByFileId, filesOrdered)
  const tplGet = (nk) => {
    if (!templateInstructionByNormCode) return ''
    if (templateInstructionByNormCode instanceof Map) {
      return templateInstructionByNormCode.get(nk) ?? ''
    }
    return String(templateInstructionByNormCode[nk] ?? '')
  }

  const displayRank = (nk) => {
    if (templateDisplayRankByNormCode instanceof Map && templateDisplayRankByNormCode.has(nk)) {
      return templateDisplayRankByNormCode.get(nk)
    }
    return 999999
  }

  const enriched = flat.map((r, flatIndex) => {
    const nk = normalizeExternalCode(r.external_code)
    const orig = tplGet(nk)
    const inTemplate = templateHasNormCode(templateInstructionByNormCode, nk)
    const cid = normalizeContractorIdForMerge(r.contractor_id)
    const contractorLabel = contractorLabelFromList(cid, contractorsList)
    return {
      ...r,
      normCode: nk,
      templateInstruction: orig,
      contractorLabel,
      _inTemplate: inTemplate,
      _templateOrder: inTemplate ? displayRank(nk) : 999999,
      _flatIndex: flatIndex
    }
  })

  return enriched.sort((a, b) => {
    const tierA = a._inTemplate ? 1 : 0
    const tierB = b._inTemplate ? 1 : 0
    if (tierA !== tierB) return tierA - tierB

    if (tierA === 0) {
      const c = a.normCode.localeCompare(b.normCode, 'ja', { numeric: true })
      if (c !== 0) return c
      return a._flatIndex - b._flatIndex
    }

    const oa = a._templateOrder
    const ob = b._templateOrder
    if (oa !== ob) return oa - ob
    const c2 = a.normCode.localeCompare(b.normCode, 'ja', { numeric: true })
    if (c2 !== 0) return c2
    return a._flatIndex - b._flatIndex
  })
}
