<template>
  <div v-if="isOpen" class="modal-overlay">
    <div class="modal-content" @mousedown.stop>
      <div class="modal-header">
        <div class="modal-header-title">
          <h3>備考編集</h3>
          <div class="slot-number">
            <span class="page-number">{{ formatCircledNumber(pageNumber) }}</span>-<span class="slot-number-value">{{ formatCircledNumber(slotNumberInPage) }}</span>
          </div>
        </div>
        <button type="button" class="close-btn" title="閉じる" @click="handleCancel">✕</button>
      </div>

      <div class="modal-body">
        <div v-if="truncatedWarning" class="warn-banner">
          11行目以降は保存時に削除されます
        </div>

        <div
          v-for="(line, index) in localLines"
          :key="line._key"
          class="note-line-row"
          :class="{
            'note-line-row--dragging': draggingKey === line._key,
            'note-line-row--drag-over': dragOverKey === line._key
          }"
          @dragenter.prevent="onRowDragEnter(line._key)"
          @dragover.prevent="onRowDragOver(line._key)"
          @dragleave="onRowDragLeave(line._key)"
          @drop.prevent="onRowDrop($event, index)"
        >
          <div
            class="drag-handle"
            draggable="true"
            title="ドラッグで並べ替え"
            @dragstart.stop="onDragStart($event, line._key)"
            @dragend.stop="onDragEnd"
          >
            ≡
          </div>
          <input
            v-model="line.text"
            type="text"
            class="line-input"
            :placeholder="`行 ${index + 1}`"
            @keydown.enter.prevent
            @dragenter.prevent="onRowDragEnter(line._key)"
            @dragover.prevent="onRowDragOver(line._key)"
            @drop.prevent="onRowDrop($event, index)"
          />
        </div>
      </div>

      <div class="modal-footer">
        <button type="button" class="cancel-btn" @click="handleCancel">キャンセル</button>
        <button type="button" class="save-btn" @click="handleSave">保存</button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue'
import { formatComparisonItemDropForNoteLine } from '../utils/compareBillingLineFormat.js'
import { formatNoteLinesForSave, formatCircledNumber } from '../utils/slotNoteConversion.js'

const LINE_COUNT = 10
const NOTE_LINE_DRAG_TYPE = 'application/x-slot-note-line-key'

const props = defineProps({
  isOpen: { type: Boolean, default: false },
  note: { type: String, default: '' },
  pageNumber: { type: Number, default: 1 },
  slotNumberInPage: { type: Number, default: 1 }
})

const emit = defineEmits(['close', 'save'])

const localLines = ref([])
const truncatedWarning = ref(false)
const draggingKey = ref(null)
const dragOverKey = ref(null)
let nextLineKey = 0

function makeLine(text = '') {
  nextLineKey += 1
  return { _key: `line-${nextLineKey}`, text }
}

function splitNoteToLines(note) {
  const parts = String(note ?? '').split('\n')
  const hadExtra = parts.length > LINE_COUNT
  const slice = parts.slice(0, LINE_COUNT)
  while (slice.length < LINE_COUNT) slice.push('')
  return { lines: slice, hadExtra }
}

function syncFromNote(note) {
  const { lines, hadExtra } = splitNoteToLines(note)
  truncatedWarning.value = hadExtra
  localLines.value = lines.map((text) => makeLine(text))
}

watch(
  () => props.isOpen,
  (open) => {
    if (open) syncFromNote(props.note)
  }
)

function onDragStart(event, key) {
  draggingKey.value = key
  event.dataTransfer.effectAllowed = 'move'
  event.dataTransfer.setData(NOTE_LINE_DRAG_TYPE, key)
  event.dataTransfer.setData('text/plain', key)
}

function onDragEnd() {
  draggingKey.value = null
  dragOverKey.value = null
}

function onRowDragEnter(key) {
  if (draggingKey.value && draggingKey.value !== key) {
    dragOverKey.value = key
  }
}

function onRowDragOver(key) {
  if (draggingKey.value && draggingKey.value !== key) {
    dragOverKey.value = key
  }
}

function onRowDragLeave(key) {
  if (dragOverKey.value === key) dragOverKey.value = null
}

function onDragReorderDropToIndex(fromKey, toIndex) {
  if (!fromKey) return
  const fromIndex = localLines.value.findIndex((l) => l._key === fromKey)
  if (fromIndex < 0 || toIndex < 0 || fromIndex === toIndex) return
  const next = [...localLines.value]
  const [moved] = next.splice(fromIndex, 1)
  next.splice(toIndex, 0, moved)
  localLines.value = next
  dragOverKey.value = null
}

function resolveReorderDragKey(event) {
  const fromState = draggingKey.value
  if (fromState && localLines.value.some((l) => l._key === fromState)) {
    return fromState
  }
  const typed = event.dataTransfer.getData(NOTE_LINE_DRAG_TYPE)
  if (typed && localLines.value.some((l) => l._key === typed)) {
    return typed
  }
  const plain = event.dataTransfer.getData('text/plain')
  if (plain && localLines.value.some((l) => l._key === plain)) {
    return plain
  }
  return null
}

function onRowDrop(event, lineIndex) {
  const reorderKey = resolveReorderDragKey(event)
  if (reorderKey) {
    onDragReorderDropToIndex(reorderKey, lineIndex)
    onDragEnd()
    return
  }

  try {
    const raw = event.dataTransfer.getData('text/plain')
    const data = JSON.parse(raw)
    if (data.type !== 'comparison-item' && data.type !== 'billing-item') return
    const formatted = formatComparisonItemDropForNoteLine(data)
    if (!formatted) return
    localLines.value = localLines.value.map((line, i) =>
      i === lineIndex ? { ...line, text: formatted } : line
    )
  } catch {
    /* ignore */
  }
}

function handleCancel() {
  emit('close')
}

function handleSave() {
  emit('save', formatNoteLinesForSave(localLines.value.map((l) => l.text ?? '')))
}
</script>

<style scoped>
.modal-overlay {
  position: fixed;
  inset: 0;
  background: transparent;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10200;
}

.modal-content {
  pointer-events: auto;
  background: #fff;
  border-radius: 8px;
  width: min(560px, 94vw);
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.22);
  border: 1px solid #e5e7eb;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.875rem 1rem;
  border-bottom: 1px solid #e5e7eb;
}

.modal-header-title {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  min-width: 0;
}

.modal-header h3 {
  margin: 0;
  font-size: 1.05rem;
  flex-shrink: 0;
}

.slot-number {
  display: flex;
  align-items: center;
  gap: 0.125rem;
  font-size: 1.25rem;
  font-weight: bold;
  white-space: nowrap;
  color: #111827;
}

.close-btn {
  flex-shrink: 0;
  border: none;
  background: transparent;
  font-size: 1.1rem;
  cursor: pointer;
  color: #6b7280;
  line-height: 1;
  padding: 0.15rem 0.35rem;
  border-radius: 4px;
}

.close-btn:hover {
  background: #f3f4f6;
  color: #374151;
}

.modal-body {
  padding: 0.75rem 1rem;
  overflow-y: auto;
}

.warn-banner {
  margin-bottom: 0.65rem;
  padding: 0.45rem 0.6rem;
  background: #fef3c7;
  color: #92400e;
  border-radius: 6px;
  font-size: 0.85rem;
}

.note-line-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 0.4rem;
  padding: 0.15rem;
  border-radius: 6px;
}

.note-line-row--drag-over {
  background: #eff6ff;
}

.note-line-row--dragging {
  opacity: 0.55;
}

.drag-handle {
  flex-shrink: 0;
  width: 1.5rem;
  text-align: center;
  color: #9ca3af;
  cursor: grab;
  user-select: none;
}

.line-input {
  flex: 1;
  min-width: 0;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  padding: 0.4rem 0.5rem;
  font-size: 0.95rem;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 0.875rem 1rem;
  border-top: 1px solid #e5e7eb;
}

.cancel-btn,
.save-btn {
  border: none;
  border-radius: 6px;
  padding: 0.45rem 1rem;
  font-size: 0.875rem;
  cursor: pointer;
}

.cancel-btn {
  background: #f3f4f6;
  color: #374151;
}

.save-btn {
  background: #2563eb;
  color: #fff;
}
</style>
