<template>
  <div v-if="isOpen" class="modal-overlay" @mousedown.stop>
    <div class="modal-content" @click.stop @mousedown.stop>
      <div class="modal-header">
        <h3>テンプレート挿入</h3>
        <button type="button" class="close-btn" @click="handleClose">✕</button>
      </div>

      <div class="modal-body">
        <p class="insert-direction">選択スロットより下にテンプレート挿入</p>
        <label class="field-label">テンプレート</label>
        <select v-model="selectedTemplateId" class="template-select">
          <option value="">選択してください</option>
          <option v-for="t in templates" :key="t.id" :value="t.id">
            {{ t.label }}
          </option>
        </select>
      </div>

      <div class="modal-footer">
        <button type="button" class="cancel-btn" @click="handleClose">キャンセル</button>
        <button
          type="button"
          class="insert-btn"
          :disabled="!selectedTemplateId || inserting"
          @click="handleInsert"
        >
          挿入
        </button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue'

const props = defineProps({
  isOpen: { type: Boolean, default: false },
  templates: { type: Array, default: () => [] },
  inserting: { type: Boolean, default: false }
})

const emit = defineEmits(['close', 'insert'])

const selectedTemplateId = ref('')

watch(
  () => props.isOpen,
  (open) => {
    if (open) selectedTemplateId.value = ''
  }
)

function handleClose() {
  emit('close')
}

function handleInsert() {
  if (!selectedTemplateId.value) return
  emit('insert', selectedTemplateId.value)
}
</script>

<style scoped>
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10200;
}

.modal-content {
  background: #fff;
  border-radius: 8px;
  width: min(420px, 92vw);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.875rem 1rem;
  border-bottom: 1px solid #e5e7eb;
}

.modal-header h3 {
  margin: 0;
  font-size: 1.05rem;
}

.close-btn {
  border: none;
  background: transparent;
  font-size: 1.1rem;
  cursor: pointer;
  color: #6b7280;
}

.modal-body {
  padding: 1rem;
}

.insert-direction {
  margin: 0 0 0.75rem;
  color: #374151;
  font-size: 0.95rem;
}

.field-label {
  display: block;
  margin-bottom: 0.35rem;
  font-size: 0.875rem;
  color: #4b5563;
}

.template-select {
  width: 100%;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  padding: 0.5rem;
  font-size: 0.95rem;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 0.875rem 1rem;
  border-top: 1px solid #e5e7eb;
}

.cancel-btn,
.insert-btn {
  border: none;
  border-radius: 6px;
  padding: 0.45rem 1rem;
  font-size: 0.875rem;
  cursor: pointer;
}

.cancel-btn {
  background: #f3f4f6;
  color: #374151;
}

.insert-btn {
  background: #2563eb;
  color: #fff;
}

.insert-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
</style>
