// PDF生成共通関数（クライアントサイド版）
// DBから取得したレイアウト情報に基づいてPDFを生成
import { PDFDocument, rgb } from 'pdf-lib'
import fontkit from 'pdf-fontkit'
import { prepareJpegBytesForPdfEmbed } from './imageResize.js'

const SUPABASE_URL = (import.meta.env.VITE_SUPABASE_URL || '').replace(/\/$/, '')
if (!SUPABASE_URL) {
  throw new Error('[pdfGeneratorCommon] VITE_SUPABASE_URL が未設定です')
}

// ★ Storage にアップした NotoSansJP-Regular / Bold の公開URL
const JP_FONT_URL = `${SUPABASE_URL}/storage/v1/object/public/settings/fonts/NotoSansJP-Regular.ttf`
const JP_FONT_BOLD_URL = `${SUPABASE_URL}/storage/v1/object/public/settings/fonts/NotoSansJP-Bold.ttf`

/** PDF embed リサイズ結果を console に出す最大件数 */
const PDF_EMBED_RESIZE_LOG_LIMIT = 10

/** 軽量 PDF（HD OFF）の既定値 */
export const PDF_EMBED_DEFAULTS = {
  embedScale: 2.0,
  embedQuality: 0.92
}

// === グリッド → PDF座標変換ヘルパー（4倍細かく） ==========================
// x = 横（左→右）, y = 縦（上→下）
// x0,y0 = 左上セル, x1,y1 = 右下セル
function cellRect(pageWidth, pageHeight, x0, y0, x1, y1, cols = 232, rows = 328) {
  const cellW = pageWidth / cols
  const cellH = pageHeight / rows
  const left = x0 * cellW
  const right = (x1 + 1) * cellW
  // PDF座標は下が0なので、yは反転させる
  const top = pageHeight - y0 * cellH
  const bottom = pageHeight - (y1 + 1) * cellH
  return {
    x: left,
    y: bottom,
    width: right - left,
    height: top - bottom,
    top,
    bottom
  }
}

// セルの枠線を引く（上/下/左/右 & 実線/点線/二重線）
function drawCellBorder(page, rect, options = {}) {
  const { color = rgb(0, 0, 0), thickness = 0.5, style = "solid", sides = ["top", "bottom", "left", "right"], dashLength = 2, dashGap = 2, doubleOffset = 1 } = options
  const topY = rect.top
  const bottomY = rect.y
  const leftX = rect.x
  const rightX = rect.x + rect.width
  const baseLineOpts = {
    color,
    thickness
  }
  const dashedOpts = style === "dashed" ? {
    dashArray: [dashLength, dashGap]
  } : {}
  
  const draw = (start, end) => {
    page.drawLine({
      start,
      end,
      ...baseLineOpts,
      ...dashedOpts
    })
  }
  
  for (const side of sides) {
    if (style === "double") {
      if (side === "top") {
        const y1 = topY
        const y2 = topY - doubleOffset
        draw({ x: leftX, y: y1 }, { x: rightX, y: y1 })
        draw({ x: leftX, y: y2 }, { x: rightX, y: y2 })
      } else if (side === "bottom") {
        const y1 = bottomY
        const y2 = bottomY + doubleOffset
        draw({ x: leftX, y: y1 }, { x: rightX, y: y1 })
        draw({ x: leftX, y: y2 }, { x: rightX, y: y2 })
      } else if (side === "left") {
        const x1 = leftX
        const x2 = leftX + doubleOffset
        draw({ x: x1, y: bottomY }, { x: x1, y: topY })
        draw({ x: x2, y: bottomY }, { x: x2, y: topY })
      } else if (side === "right") {
        const x1 = rightX
        const x2 = rightX - doubleOffset
        draw({ x: x1, y: bottomY }, { x: x1, y: topY })
        draw({ x: x2, y: bottomY }, { x: x2, y: topY })
      }
    } else {
      if (side === "top") {
        draw({ x: leftX, y: topY }, { x: rightX, y: topY })
      } else if (side === "bottom") {
        draw({ x: leftX, y: bottomY }, { x: rightX, y: bottomY })
      } else if (side === "left") {
        draw({ x: leftX, y: bottomY }, { x: leftX, y: topY })
      } else if (side === "right") {
        draw({ x: rightX, y: bottomY }, { x: rightX, y: topY })
      }
    }
  }
}

// セル内の文字を「縦中央」＋「横 左/中央/右」を選べる版
const HALF_WIDTH_DIGIT_TRAILING_TIGHTEN_RATIO = 0

function isHalfWidthDigit(char) {
  return /^[0-9]$/.test(char)
}

function getTightenedTextWidth(text, font, size) {
  const chars = Array.from(String(text))
  if (!chars.some(isHalfWidthDigit)) {
    return font.widthOfTextAtSize(text, size)
  }

  return chars.reduce((width, char, index) => {
    const tighten = isHalfWidthDigit(char) && index < chars.length - 1
      ? size * HALF_WIDTH_DIGIT_TRAILING_TIGHTEN_RATIO
      : 0
    return width + Math.max(0, font.widthOfTextAtSize(char, size) - tighten)
  }, 0)
}

function drawTextWithHalfDigitTightening(page, text, opts) {
  if (!/[0-9]/.test(text)) {
    page.drawText(text, opts)
    return
  }

  const chars = Array.from(String(text))
  let cursorX = opts.x
  for (let i = 0; i < chars.length; i++) {
    const char = chars[i]
    page.drawText(char, {
      ...opts,
      x: cursorX
    })
    const tighten = isHalfWidthDigit(char) && i < chars.length - 1
      ? opts.size * HALF_WIDTH_DIGIT_TRAILING_TIGHTEN_RATIO
      : 0
    cursorX += Math.max(0, opts.font.widthOfTextAtSize(char, opts.size) - tighten)
  }
}

function drawTextFitInRectMiddle(page, text, rect, opts) {
  if (!text) return
  const { font, maxSize, minSize = 4, color = rgb(0, 0, 0), padding = 2, hAlign = "left" } = opts
  const maxWidth = rect.width - padding * 2
  let size = maxSize
  let width = getTightenedTextWidth(text, font, size)
  if (width > maxWidth) {
    const ratio = maxWidth / width
    size = Math.max(minSize, size * ratio)
    width = getTightenedTextWidth(text, font, size)
  }
  const textHeight = font.heightAtSize(size)
  let x
  if (hAlign === "center") {
    const rawX = rect.x + (rect.width - width) / 2
    const minX = rect.x + padding
    const maxX = rect.x + rect.width - padding - width
    x = Math.max(minX, Math.min(rawX, maxX))
  } else if (hAlign === "right") {
    x = rect.x + rect.width - width - padding
  } else {
    x = rect.x + padding
  }
  const y = rect.y + (rect.height - textHeight) / 2
  drawTextWithHalfDigitTightening(page, text, {
    x,
    y,
    size,
    font,
    color
  })
}

// RGB配列をrgbオブジェクトに変換
function rgbFromArray(arr) {
  if (!Array.isArray(arr) || arr.length < 3) {
    return rgb(0, 0, 0)
  }
  return rgb(arr[0] / 255, arr[1] / 255, arr[2] / 255)
}

/**
 * レイアウト内の画像要素から、URL+rotation ごとの最大 embed 枠（px）を収集
 */
function collectPdfImageEmbedBoxes(layouts, pageWidth, pageHeight, cols, rows, embedScale) {
  const map = new Map()

  if (!Array.isArray(layouts)) return map

  for (const layout of layouts) {
    if (!layout || !Array.isArray(layout.elements)) continue
    for (const element of layout.elements) {
      if (element?.elementType !== 'image' || !element.config?.imageUrl || !element.position) continue

      const url = String(element.config.imageUrl).trim()
      if (!url) continue

      const rotation = element.config?.rotation || 0
      const imageKey = rotation !== 0 && rotation !== 360 ? `${url}__rotation_${rotation}` : url
      const rect = cellRect(
        pageWidth,
        pageHeight,
        element.position.x0,
        element.position.y0,
        element.position.x1,
        element.position.y1,
        cols,
        rows
      )
      const boxW = Math.max(1, Math.ceil(rect.width * embedScale))
      const boxH = Math.max(1, Math.ceil(rect.height * embedScale))

      const prev = map.get(imageKey)
      if (!prev) {
        map.set(imageKey, { url, rotation, maxWidth: boxW, maxHeight: boxH })
      } else {
        prev.maxWidth = Math.max(prev.maxWidth, boxW)
        prev.maxHeight = Math.max(prev.maxHeight, boxH)
      }
    }
  }

  return map
}

/** 回転のみ（フル解像度 embed 用）。JPEG 再エンコードあり */
async function rotateImageWithCanvas(imageBytes, rotationDeg, jpegQuality = 0.92) {
  if (rotationDeg === 0 || rotationDeg === 360) {
    return imageBytes
  }

  return new Promise((resolve, reject) => {
    const img = new Image()
    const blob = new Blob([imageBytes])
    const imgUrl = URL.createObjectURL(blob)

    img.onload = () => {
      try {
        const canvas = document.createElement('canvas')
        const ctx = canvas.getContext('2d')

        const rad = (rotationDeg * Math.PI) / 180
        const cos = Math.abs(Math.cos(rad))
        const sin = Math.abs(Math.sin(rad))
        const w = img.width * cos + img.height * sin
        const h = img.width * sin + img.height * cos

        canvas.width = w
        canvas.height = h

        ctx.translate(w / 2, h / 2)
        ctx.rotate(rad)
        ctx.drawImage(img, -img.width / 2, -img.height / 2)

        canvas.toBlob((outBlob) => {
          if (!outBlob) {
            URL.revokeObjectURL(imgUrl)
            reject(new Error('Canvas to Blob conversion failed'))
            return
          }

          outBlob.arrayBuffer().then((buffer) => {
            URL.revokeObjectURL(imgUrl)
            resolve(new Uint8Array(buffer))
          }).catch(reject)
        }, 'image/jpeg', jpegQuality)
      } catch (error) {
        URL.revokeObjectURL(imgUrl)
        reject(error)
      }
    }

    img.onerror = () => {
      URL.revokeObjectURL(imgUrl)
      reject(new Error('Failed to load image'))
    }

    img.src = imgUrl
  })
}

async function embedPdfImages(pdfDoc, layouts, pageWidth, pageHeight, cols, rows, options = {}) {
  const {
    highResolutionPdf = false,
    embedScale = PDF_EMBED_DEFAULTS.embedScale,
    embedQuality = PDF_EMBED_DEFAULTS.embedQuality
  } = options

  const embeddedImages = new Map()
  const embedBoxMap = collectPdfImageEmbedBoxes(layouts, pageWidth, pageHeight, cols, rows, embedScale)
  let pdfEmbedResizeLogCount = 0

  for (const [imageKey, info] of embedBoxMap) {
    try {
      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), 30000)

      const imgRes = await fetch(info.url, {
        credentials: 'omit',
        signal: controller.signal
      })

      clearTimeout(timeoutId)

      if (!imgRes.ok) continue

      const originalImgBytes = new Uint8Array(await imgRes.arrayBuffer())
      const contentType = imgRes.headers.get('content-type') || ''
      const isPng = contentType.includes('png') || info.url.toLowerCase().includes('.png')

      if (highResolutionPdf) {
        let imgBytes = originalImgBytes
        if (info.rotation !== 0 && info.rotation !== 360) {
          imgBytes = await rotateImageWithCanvas(originalImgBytes, info.rotation, embedQuality)
        }

        let embeddedImage
        if (isPng && (info.rotation === 0 || info.rotation === 360)) {
          embeddedImage = await pdfDoc.embedPng(imgBytes)
        } else {
          embeddedImage = await pdfDoc.embedJpg(imgBytes)
        }
        embeddedImages.set(imageKey, embeddedImage)

        if (pdfEmbedResizeLogCount < PDF_EMBED_RESIZE_LOG_LIMIT) {
          pdfEmbedResizeLogCount += 1
          console.info('[PDF embed full]', {
            index: pdfEmbedResizeLogCount,
            url: info.url,
            rotation: info.rotation,
            mode: 'highResolution',
            jpegKB: Math.round(imgBytes.byteLength / 1024)
          })
        }
        continue
      }

      const prepared = await prepareJpegBytesForPdfEmbed(originalImgBytes, {
        maxWidth: info.maxWidth,
        maxHeight: info.maxHeight,
        rotation: info.rotation,
        quality: embedQuality
      })

      if (pdfEmbedResizeLogCount < PDF_EMBED_RESIZE_LOG_LIMIT) {
        pdfEmbedResizeLogCount += 1
        console.info('[PDF embed resize]', {
          index: pdfEmbedResizeLogCount,
          url: info.url,
          rotation: info.rotation,
          mode: 'standard',
          sourcePx: `${prepared.sourceWidth}×${prepared.sourceHeight}`,
          embedBoxPx: `${info.maxWidth}×${info.maxHeight}`,
          outputPx: `${prepared.outputWidth}×${prepared.outputHeight}`,
          jpegKB: Math.round(prepared.jpegBytesSize / 1024)
        })
      }

      const embeddedImage = await pdfDoc.embedJpg(prepared.jpegBytes)
      embeddedImages.set(imageKey, embeddedImage)
    } catch (e) {
      console.error(`画像読み込みエラー: ${info.url}`, e)
    }
  }

  return embeddedImages
}

// レイアウト要素を描画
async function renderElement(page, element, pageWidth, pageHeight, pageValues, embeddedImages, jpFont, jpFontBold, cols, rows) {
  const { elementType, position, config } = element
  
  if (!position || !config) return
  
  const rect = cellRect(pageWidth, pageHeight, position.x0, position.y0, position.x1, position.y1, cols, rows)
  
  switch (elementType) {
    case 'text': {
      // テキストはconfig.textから直接取得、またはvaluesから取得
      let text = config.text || ''
      
      // valuesから取得する場合（configにtextIndexやtextSourceが指定されている場合）
      if (config.textSource && pageValues) {
        const source = config.textSource // 'caption', 'phase', 'note'など
        const index = config.textIndex !== undefined ? config.textIndex : 0
        
        if (source === 'caption' && pageValues.caption && Array.isArray(pageValues.caption)) {
          text = pageValues.caption[index] || ''
        } else if (source === 'phase' && pageValues.phase && Array.isArray(pageValues.phase)) {
          text = pageValues.phase[index] || ''
        } else if (source === 'note' && pageValues.note && Array.isArray(pageValues.note)) {
          text = pageValues.note[index] || ''
        }
      }
      
      const fontSize = config.fontSize || 10
      const fontWeight = config.fontWeight || 'normal'
      const align = config.align || 'left'
      const color = rgbFromArray(config.color || [0, 0, 0])
      const font = fontWeight === 'bold' ? jpFontBold : jpFont
      
      drawTextFitInRectMiddle(page, text, rect, {
        font,
        maxSize: fontSize,
        minSize: fontSize * 0.5,
        color,
        hAlign: align
      })
      break
    }
    
    case 'image': {
      // imageUrlがconfigに直接含まれている場合（エッジファンクションで展開済み）
      let imageUrl = config.imageUrl
      // rotationはconfigから取得（エッジファンクションで展開済み）
      const rotation = config.rotation || 0
      
      // imageUrlがない場合、imageIndexから取得
      if (!imageUrl && config.imageIndex !== undefined && pageValues && pageValues.image && Array.isArray(pageValues.image)) {
        imageUrl = pageValues.image[config.imageIndex]
      }
      
      if (imageUrl) {
        // rotationがある場合は、回転後の画像キーを使用
        const imageKey = rotation !== 0 ? `${imageUrl}__rotation_${rotation}` : imageUrl
        const embeddedImage = embeddedImages.get(imageKey) || embeddedImages.get(imageUrl)
        
        if (embeddedImage) {
          const imgSize = embeddedImage.scale(1)
          const maxW = rect.width
          const maxH = rect.height
          const fit = config.fit || 'contain'
          
          let scale, drawW, drawH
          if (fit === 'cover') {
            scale = Math.max(maxW / imgSize.width, maxH / imgSize.height)
          } else if (fit === 'fill') {
            drawW = maxW
            drawH = maxH
            scale = 1
          } else { // contain
            scale = Math.min(maxW / imgSize.width, maxH / imgSize.height)
          }
          
          if (fit !== 'fill') {
            drawW = imgSize.width * scale
            drawH = imgSize.height * scale
          }
          
          const imgX = rect.x + (maxW - drawW) / 2
          const imgY = rect.y + (maxH - drawH) / 2
          
          page.drawImage(embeddedImage, {
            x: imgX,
            y: imgY,
            width: drawW,
            height: drawH
          })
        }
      }
      break
    }
    
    case 'line':
    case 'border': {
      const lineType = config.lineType || config.borderType || 'solid'
      const thickness = config.thickness || 0.5
      const color = rgbFromArray(config.color || [0, 0, 0])
      const sides = config.sides || ['top', 'bottom', 'left', 'right']
      
      let style = 'solid'
      if (lineType === 'dashed') style = 'dashed'
      else if (lineType === 'double') style = 'double'
      
      drawCellBorder(page, rect, {
        style,
        thickness,
        color,
        sides
      })
      break
    }
  }
}

// メインPDF生成関数
export async function generatePDFFromLayout(layoutData, values, pdfOptions = {}) {
  try {
    const { pdf_type, page_count, layouts, grid } = layoutData
    const { cols = 232, rows = 328 } = grid || {}
    
    const pdfDoc = await PDFDocument.create()
    pdfDoc.registerFontkit(fontkit)
    
    // 日本語フォント読み込み
    const fontRes = await fetch(JP_FONT_URL)
    const fontBoldRes = await fetch(JP_FONT_BOLD_URL)
    if (!fontRes.ok || !fontBoldRes.ok) {
      throw new Error(`フォント取得失敗: ${fontRes.status}, ${fontBoldRes.status}`)
    }
    
    const fontBytes = new Uint8Array(await fontRes.arrayBuffer())
    const fontBoldBytes = new Uint8Array(await fontBoldRes.arrayBuffer())
    const jpFont = await pdfDoc.embedFont(fontBytes, { subset: true })
    const jpFontBold = await pdfDoc.embedFont(fontBoldBytes, { subset: true })
    
    // A4縦
    const pageWidth = 595
    const pageHeight = 842
    
    // 画像を埋め込む
    const embeddedImages = await embedPdfImages(
      pdfDoc,
      layouts,
      pageWidth,
      pageHeight,
      cols,
      rows,
      pdfOptions
    )
    
    // ページを生成
    const pages = []
    
    // 表紙がある場合
    const coverLayout = layouts.find(l => l.pageNumber === 0)
    if (coverLayout) {
      const coverPage = pdfDoc.addPage([pageWidth, pageHeight])
      pages.push({ page: coverPage, pageNumber: 0 })
      
      // 表紙用のvalues（values配列からpage=0のものを探す、なければnull）
      const coverValues = values && Array.isArray(values) ? values.find(v => v.page === 0) : null
      
      for (const element of coverLayout.elements) {
        await renderElement(coverPage, element, pageWidth, pageHeight, coverValues, embeddedImages, jpFont, jpFontBold, cols, rows)
      }
    }
    
    // 各ページを生成
    for (let pageNum = 1; pageNum <= page_count; pageNum++) {
      const page = pdfDoc.addPage([pageWidth, pageHeight])
      pages.push({ page, pageNumber: pageNum })
      
      // 該当ページの値（values配列から該当ページのデータを取得）
      const pageValues = values.find(v => v.page === pageNum)
      
      // 該当ページのレイアウト
      const pageLayout = layouts.find(l => l.pageNumber === pageNum)
      // 全ページ共通のレイアウト
      const commonLayout = layouts.find(l => l.pageNumber === null)
      
      // 全ページ共通の要素を描画
      if (commonLayout) {
        for (const element of commonLayout.elements) {
          await renderElement(page, element, pageWidth, pageHeight, pageValues, embeddedImages, jpFont, jpFontBold, cols, rows)
        }
      }
      
      // ページ固有の要素を描画
      if (pageLayout) {
        for (const element of pageLayout.elements) {
          await renderElement(page, element, pageWidth, pageHeight, pageValues, embeddedImages, jpFont, jpFontBold, cols, rows)
        }
      }
    }
    
    const bytes = await pdfDoc.save()
    return bytes
  } catch (e) {
    console.error("PDF生成エラー:", e)
    throw e
  }
}

