/** 施工前後: ドロップ追加行（保存形式は code\\tdesc\\tcontent） */
export function parseCompareDroppedBillingLine(line) {
  const s = String(line ?? '').trim()
  if (!s) return { code: '', desc: '', content: '' }
  if (s.includes('\t')) {
    const parts = s.split('\t')
    return {
      code: (parts[0] || '').trim(),
      desc: (parts[1] || '').trim(),
      content: (parts[2] || '').trim()
    }
  }
  const tokens = s.split(/\s+/).filter(Boolean)
  if (tokens.length >= 2) {
    return { code: tokens[0], desc: tokens.slice(1).join(' '), content: '' }
  }
  return { code: '', desc: s, content: '' }
}

/** 追加項目の表示（単価コードなし・登録工事の内容行と同型） */
export function formatCompareDroppedBillingLineForPanel(line) {
  const { desc, content } = parseCompareDroppedBillingLine(line)
  if (!desc && !content) return ''
  if (content) return desc ? `${desc} 内容:${content}` : `内容:${content}`
  return desc
}

/** comparison-item ドラッグデータから備考1行分の文字列を生成 */
export function formatComparisonItemDropForNoteLine(data) {
  if (!data || typeof data !== 'object') return ''
  if (data.type === 'billing-item' && data.external_code) {
    return `\${${data.external_code}}`
  }
  if (data.type === 'comparison-item') {
    const code = String(data.external_code || '').trim()
    const desc = String(
      data.billing_description || data.description || ''
    ).trim()
    const content = String(
      data.estimate_instruction || data.content || ''
    ).trim()
    const rawLine = [code, desc, content].join('\t')
    return formatCompareDroppedBillingLineForPanel(rawLine)
  }
  return ''
}
