<template>
  <Teleport to="body">
    <div v-if="isOpen" class="modal-overlay" @click="handleClose">
      <div class="modal-content" @click.stop>
      <!-- 常に同じ寸法の黒枠。閉じる・回転はこの枠基準で固定（読込・回転でガタつかない） -->
        <div class="modal-stage" :style="fixedStageStyle">
        <div
          v-if="assignmentEntries.length > 0"
          class="modal-assignment-bar"
          @click.stop
        >
          <button
            v-for="entry in assignmentEntries"
            :key="entry.slotId"
            type="button"
            class="modal-assignment-btn"
            @click.stop="emit('assignment-click', entry.slotId)"
          >
            割当{{ entry.label }}
          </button>
        </div>
        <button type="button" class="modal-close" @click="handleClose">×</button>
        <button
          v-if="enableRotate && file.fullImageUrl && !isLoading && imageReady"
          type="button"
          class="modal-rotate-btn"
          @click="handleRotate"
          title="画像を回転（90度）"
        >
          ⤵
        </button>
        <button
          v-if="showNavigation"
          type="button"
          class="modal-nav-btn modal-nav-btn--prev"
          :disabled="!canNavigatePrev"
          @click.stop="onNavigatePrev"
          title="前の画像"
        >
          ＜
        </button>
        <button
          v-if="showNavigation"
          type="button"
          class="modal-nav-btn modal-nav-btn--next"
          :disabled="!canNavigateNext"
          @click.stop="onNavigateNext"
          title="次の画像"
        >
          ＞
        </button>
        <div class="modal-stage-fill">
          <div
            v-if="file.fullImageUrl && !isLoading"
            v-show="imageReady"
            ref="imageWrapRef"
            class="modal-image-wrap"
            :class="{ 'is-zoomed': zoomActive, 'is-panning': isPanning }"
            :style="wrapStyle"
            @pointerdown="onWrapPointerDown"
          >
            <img
              :src="file.fullImageUrl"
              :alt="file.original_name || '画像'"
              class="modal-image"
              draggable="false"
              @load="onImgLoad"
              @click="onImageClick"
            />
          </div>
          <div v-if="showLoadingInStage" class="modal-loading-inner">
            <div class="modal-loading-spinner"></div>
            <div class="modal-loading-text">読み込み中</div>
          </div>
        </div>
      </div>
        <div class="modal-info">
        <div class="modal-file-name">{{ file.original_name || '無名ファイル' }}</div>
        <div v-if="file.size_bytes" class="modal-file-size">
          {{ formatFileSize(file.size_bytes) }}
        </div>
      </div>
    </div>
    </div>
  </Teleport>
</template>

<script setup>
import { computed, defineProps, defineEmits, onMounted, onUnmounted, ref, watch } from 'vue'

defineOptions({ inheritAttrs: false })

const ZOOM_SCALE = 2.3
const PAN_DRAG_THRESHOLD = 5

const props = defineProps({
  file: {
    type: Object,
    required: true
  },
  isLoading: {
    type: Boolean,
    default: false
  },
  enableRotate: {
    type: Boolean,
    default: true
  },
  showNavigation: {
    type: Boolean,
    default: false
  },
  canNavigatePrev: {
    type: Boolean,
    default: false
  },
  canNavigateNext: {
    type: Boolean,
    default: false
  },
  assignmentEntries: {
    type: Array,
    default: () => []
  }
})

const emit = defineEmits(['close', 'rotate', 'navigate-prev', 'navigate-next', 'assignment-click'])

const isOpen = computed(() => !!props.file)

const viewport = ref({ w: 1024, h: 768 })
const imgNatural = ref({ w: 0, h: 0 })
const imageWrapRef = ref(null)

const zoomActive = ref(false)
const panX = ref(0)
const panY = ref(0)
const isPanning = ref(false)
const panMoved = ref(false)
/** pointerup でズーム解除した直後の click を無視する */
const suppressImageClick = ref(false)

let activePointerId = null
let panStartX = 0
let panStartY = 0
let panBaseX = 0
let panBaseY = 0

function syncViewport() {
  if (typeof window === 'undefined') return
  viewport.value = { w: window.innerWidth, h: window.innerHeight }
}

function endPanListeners() {
  window.removeEventListener('pointermove', onPointerMove)
  window.removeEventListener('pointerup', onPointerUp)
  window.removeEventListener('pointercancel', onPointerUp)
}

function resetZoom() {
  zoomActive.value = false
  panX.value = 0
  panY.value = 0
  isPanning.value = false
  panMoved.value = false
  suppressImageClick.value = false
  activePointerId = null
  endPanListeners()
}

onMounted(() => {
  syncViewport()
  window.addEventListener('resize', syncViewport)
})

onUnmounted(() => {
  window.removeEventListener('resize', syncViewport)
  endPanListeners()
})

const maxStageW = computed(() => {
  const w = viewport.value.w
  return w <= 900 ? Math.min(800, w * 0.94) : Math.min(800, w * 0.92)
})

const maxStageH = computed(() => {
  const w = viewport.value.w
  const h = viewport.value.h
  return w <= 900 ? Math.min(800, h * 0.7) : Math.min(800, h * 0.85)
})

/** 外枠は常にこのサイズ（読込前後・回転で不変） */
const fixedStageStyle = computed(() => ({
  width: `${maxStageW.value}px`,
  height: `${maxStageH.value}px`,
  maxWidth: '100%',
  boxSizing: 'border-box'
}))

const imageReady = computed(
  () => imgNatural.value.w > 0 && imgNatural.value.h > 0
)

function onImgLoad(e) {
  const el = e.target
  const nw = el.naturalWidth || 0
  const nh = el.naturalHeight || 0
  if (nw > 0 && nh > 0) {
    imgNatural.value = { w: nw, h: nh }
  }
}

const rotationNorm = computed(() => {
  const r = Number(props.file?.rotation) || 0
  return ((r % 360) + 360) % 360
})

watch(
  () => [props.file?.id, props.file?.fullImageUrl],
  () => {
    imgNatural.value = { w: 0, h: 0 }
    resetZoom()
  }
)

watch(rotationNorm, () => {
  resetZoom()
})

const showLoadingInStage = computed(
  () =>
    props.isLoading ||
    !props.file?.fullImageUrl ||
    (props.file?.fullImageUrl && !props.isLoading && !imageReady.value)
)

function fitDisplaySize() {
  const cw = maxStageW.value
  const ch = maxStageH.value
  const nw = imgNatural.value.w
  const nh = imgNatural.value.h
  const r = rotationNorm.value
  if (!nw || !nh) return null
  const swap = r === 90 || r === 270
  const s = swap ? Math.min(cw / nh, ch / nw) : Math.min(cw / nw, ch / nh)
  return { w: nw * s, h: nh * s }
}

const wrapStyle = computed(() => {
  const size = fitDisplaySize()
  if (!size) return {}
  const r = rotationNorm.value
  const transforms = []
  if (zoomActive.value) {
    transforms.push(`translate(${panX.value}px, ${panY.value}px)`)
    transforms.push(`scale(${ZOOM_SCALE})`)
  }
  if (r) transforms.push(`rotate(${r}deg)`)
  return {
    width: `${size.w}px`,
    height: `${size.h}px`,
    transform: transforms.length ? transforms.join(' ') : undefined,
    transformOrigin: 'center center',
    flexShrink: '0'
  }
})

function applyZoomAt(clientX, clientY) {
  const wrap = imageWrapRef.value
  if (!wrap) return
  const wr = wrap.getBoundingClientRect()
  const cx = wr.left + wr.width / 2
  const cy = wr.top + wr.height / 2
  const ox = clientX - cx
  const oy = clientY - cy
  panX.value = ox * (1 - ZOOM_SCALE)
  panY.value = oy * (1 - ZOOM_SCALE)
  zoomActive.value = true
}

function onImageClick(e) {
  e.stopPropagation()
  if (suppressImageClick.value) {
    suppressImageClick.value = false
    return
  }
  if (panMoved.value) return
  if (!zoomActive.value) {
    applyZoomAt(e.clientX, e.clientY)
  }
}

function onWrapPointerDown(e) {
  if (!zoomActive.value || e.button !== 0) return
  e.stopPropagation()
  isPanning.value = true
  panMoved.value = false
  activePointerId = e.pointerId
  panStartX = e.clientX
  panStartY = e.clientY
  panBaseX = panX.value
  panBaseY = panY.value
  try {
    e.currentTarget?.setPointerCapture?.(e.pointerId)
  } catch {
    /* ignore */
  }
  window.addEventListener('pointermove', onPointerMove)
  window.addEventListener('pointerup', onPointerUp)
  window.addEventListener('pointercancel', onPointerUp)
}

function onPointerMove(e) {
  if (!isPanning.value || e.pointerId !== activePointerId) return
  const dx = e.clientX - panStartX
  const dy = e.clientY - panStartY
  if (Math.hypot(dx, dy) >= PAN_DRAG_THRESHOLD) {
    panMoved.value = true
  }
  panX.value = panBaseX + dx
  panY.value = panBaseY + dy
}

function onPointerUp(e) {
  if (e.pointerId !== activePointerId) return
  const tapToReset = zoomActive.value && !panMoved.value
  isPanning.value = false
  activePointerId = null
  endPanListeners()
  if (tapToReset) {
    resetZoom()
    suppressImageClick.value = true
  }
}

function onNavigatePrev() {
  resetZoom()
  emit('navigate-prev')
}

function onNavigateNext() {
  resetZoom()
  emit('navigate-next')
}

function handleClose() {
  resetZoom()
  emit('close')
}

function handleRotate() {
  resetZoom()
  emit('rotate')
}

function formatFileSize(bytes) {
  if (!bytes) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}
</script>

